      function buildStatusIndicatorItem(id, profile) {
        if (id === "google-drive") {
          return {
            id: "google-drive",
            title: "Google Drive connected",
            copy: profile?.email || profile?.username || "Successfully connected",
            logoUrl: "https://upload.wikimedia.org/wikipedia/commons/1/12/Google_Drive_icon_%282020%29.svg",
          };
        }

        if (id === "one-drive") {
          return {
            id: "one-drive",
            title: "OneDrive connected",
            copy: profile?.email || profile?.username || "Successfully connected",
            logoUrl: "https://upload.wikimedia.org/wikipedia/commons/5/59/Microsoft_Office_OneDrive_%282019%E2%80%932025%29.svg",
          };
        }

        if (id === "github") {
          return {
            id: "github",
            title: "GitHub connected",
            copy: profile?.email || profile?.login || profile?.name || "Successfully connected",
            brand: "github",
          };
        }

        if (id === "notion") {
          return {
            id: "notion",
            title: "Notion connected",
            copy: profile?.workspaceName || profile?.name || profile?.email || "Successfully connected",
            logoUrl: "https://upload.wikimedia.org/wikipedia/commons/e/e9/Notion-logo.svg",
          };
        }

        if (id === "gmail") {
          return {
            id: "gmail",
            title: "Gmail connected",
            copy: profile?.email || profile?.username || "Successfully connected",
            logoUrl: PLAYGROUND_GMAIL_LOGO_URL,
          };
        }

        return null;
      }

      function buildTaskRunStatusIndicatorItem(taskRunState) {
        const normalizedTaskId = typeof taskRunState?.taskId === "string" ? taskRunState.taskId.trim() : "";
        if (!normalizedTaskId) {
          return null;
        }

        const ticketPrefix = typeof taskRunState?.ticketNumber === "string" && taskRunState.ticketNumber.trim()
          ? taskRunState.ticketNumber.trim() + " "
          : "";
        const taskLabel = ticketPrefix + (typeof taskRunState?.title === "string" && taskRunState.title.trim()
          ? taskRunState.title.trim()
          : "Untitled Task");
        const phase = typeof taskRunState?.phase === "string" ? taskRunState.phase.trim().toLowerCase() : "";
        const runKind = typeof taskRunState?.runKind === "string" ? taskRunState.runKind.trim().toLowerCase() : "";

        if (phase === "starting") {
          return {
            id: "task-run:" + normalizedTaskId,
            title: runKind === "review" ? "Review scheduled" : "Task scheduled",
            copy: taskLabel + " will begin shortly.",
          };
        }

        if (phase === "running") {
          return {
            id: "task-run:" + normalizedTaskId,
            title: runKind === "review" ? "Review running" : "Task running",
            copy: taskLabel,
          };
        }

        if (phase === "finished") {
          return {
            id: "task-run:" + normalizedTaskId,
            title: runKind === "review" ? "Review accepted" : "Task finished",
            copy: taskLabel,
          };
        }

        if (phase === "in_review") {
          return {
            id: "task-run:" + normalizedTaskId,
            title: runKind === "review" ? "Review finished" : "Task ready for review",
            copy: taskLabel,
          };
        }

        if (phase === "waiting_subtasks") {
          return {
            id: "task-run:" + normalizedTaskId,
            title: "Task waiting on subtasks",
            copy: typeof taskRunState?.error === "string" && taskRunState.error.trim()
              ? taskRunState.error.trim()
              : taskLabel,
          };
        }

        if (phase === "failed") {
          return {
            id: "task-run:" + normalizedTaskId,
            title: "Task failed to start",
            copy: typeof taskRunState?.error === "string" && taskRunState.error.trim()
              ? taskRunState.error.trim()
              : taskLabel,
          };
        }

        if (phase === "cancelled") {
          return {
            id: "task-run:" + normalizedTaskId,
            title: "Task cancelled",
            copy: taskLabel,
          };
        }

        return null;
      }

      function buildMissionControlStatusIndicatorItem(runState) {
        const normalizedProjectId = typeof runState?.projectId === "string" ? runState.projectId.trim() : "";
        if (!normalizedProjectId) {
          return null;
        }

        const projectName = typeof runState?.projectName === "string" && runState.projectName.trim()
          ? runState.projectName.trim()
          : "Project";
        const missionLabel = projectName + " Mission Control";
        const phase = typeof runState?.phase === "string" ? runState.phase.trim().toLowerCase() : "";

        if (phase === "starting") {
          return {
            id: "mission-control:" + normalizedProjectId,
            title: "Mission Control scheduled",
            copy: missionLabel + " will begin shortly.",
          };
        }

        if (phase === "running") {
          return {
            id: "mission-control:" + normalizedProjectId,
            title: "Mission Control running",
            copy: missionLabel,
          };
        }

        if (phase === "finished") {
          return {
            id: "mission-control:" + normalizedProjectId,
            title: "Mission Control finished",
            copy: missionLabel,
          };
        }

        if (phase === "failed") {
          return {
            id: "mission-control:" + normalizedProjectId,
            title: "Mission Control failed to start",
            copy: typeof runState?.error === "string" && runState.error.trim()
              ? runState.error.trim()
              : missionLabel,
          };
        }

        if (phase === "cancelled") {
          return {
            id: "mission-control:" + normalizedProjectId,
            title: "Mission Control cancelled",
            copy: missionLabel,
          };
        }

        return null;
      }

      function buildProjectGithubPreparationStatusIndicatorItem(preparationState) {
        const normalizedProjectId = typeof preparationState?.projectId === "string" ? preparationState.projectId.trim() : "";
        const normalizedRepoFullName = typeof preparationState?.repoFullName === "string" ? preparationState.repoFullName.trim() : "";
        if (!normalizedProjectId || !normalizedRepoFullName) {
          return null;
        }

        const environmentLabel = typeof preparationState?.environmentName === "string" && preparationState.environmentName.trim()
          ? preparationState.environmentName.trim()
          : "project environment";
        const branchLabel = typeof preparationState?.branch === "string" && preparationState.branch.trim()
          ? preparationState.branch.trim()
          : "main";
        const phase = typeof preparationState?.phase === "string" ? preparationState.phase.trim().toLowerCase() : "";
        const id = "project-github-prepare:" + normalizedProjectId + ":" + normalizedRepoFullName + ":" + branchLabel;

        if (phase === "starting" || phase === "running") {
          return {
            id,
            title: "Preparing GitHub repository",
            copy: normalizedRepoFullName + " into " + environmentLabel,
            brand: "github",
            progress: null,
            indeterminate: true,
          };
        }

        if (phase === "finished") {
          return {
            id,
            title: "GitHub repository ready",
            copy: normalizedRepoFullName + " is available in " + environmentLabel,
            brand: "github",
            progress: null,
            indeterminate: false,
          };
        }

        if (phase === "failed") {
          return {
            id,
            title: "GitHub repository sync failed",
            copy: typeof preparationState?.error === "string" && preparationState.error.trim()
              ? preparationState.error.trim()
              : normalizedRepoFullName,
            brand: "github",
            progress: null,
            indeterminate: false,
          };
        }

        return null;
      }

      function buildServerDeployStatusIndicatorItem(deployState) {
        const normalizedServerId = typeof deployState?.serverId === "string" ? deployState.serverId.trim() : "";
        if (!normalizedServerId) {
          return null;
        }

        const serverLabel = typeof deployState?.serverName === "string" && deployState.serverName.trim()
          ? deployState.serverName.trim()
          : "Server";
        const phase = typeof deployState?.phase === "string" ? deployState.phase.trim().toLowerCase() : "";

        if (phase === "starting" || phase === "running") {
          return {
            id: "server-deploy:" + normalizedServerId,
            title: "Deployment started",
            copy: serverLabel,
            indeterminate: true,
          };
        }

        if (phase === "finished") {
          return {
            id: "server-deploy:" + normalizedServerId,
            title: "Deployment finished",
            copy: typeof deployState?.serviceUrl === "string" && deployState.serviceUrl.trim()
              ? deployState.serviceUrl.trim()
              : serverLabel,
            progress: 100,
          };
        }

        if (phase === "failed") {
          return {
            id: "server-deploy:" + normalizedServerId,
            title: "Deployment failed",
            copy: typeof deployState?.error === "string" && deployState.error.trim()
              ? deployState.error.trim()
              : serverLabel,
          };
        }

        return null;
      }

      function getAccountInitials(value) {
        const normalized = String(value || "").trim();
        if (!normalized) {
          return "CA";
        }

        const emailPrefix = normalized.includes("@") ? normalized.split("@")[0] : normalized;
        const parts = emailPrefix
          .split(/[^a-zA-Z0-9]+/)
          .map((part) => part.trim())
          .filter(Boolean);

        if (parts.length === 0) {
          return emailPrefix.slice(0, 2).toUpperCase();
        }

        if (parts.length === 1) {
          return parts[0].slice(0, 2).toUpperCase();
        }

        return (parts[0][0] + parts[1][0]).toUpperCase();
      }

      function formatEmailPrefixDisplayName(value) {
        const normalizedValue = String(value || "").trim();
        if (!normalizedValue) {
          return "";
        }

        const emailPrefix = normalizedValue.includes("@") ? normalizedValue.split("@")[0] : normalizedValue;
        const parts = emailPrefix
          .split(/[^a-zA-Z0-9]+/)
          .map((part) => part.trim())
          .filter(Boolean);

        if (parts.length === 0) {
          return emailPrefix;
        }

        return parts
          .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
          .join(" ");
      }

      function getTrustedDisplayName(displayName, email) {
        const normalizedDisplayName = String(displayName || "").replace(/\\s+/g, " ").trim();
        if (!normalizedDisplayName) {
          return "";
        }

        const derivedEmailName = formatEmailPrefixDisplayName(email);
        if (
          derivedEmailName
          && normalizedDisplayName.localeCompare(derivedEmailName, undefined, { sensitivity: "accent" }) === 0
        ) {
          return "";
        }

        return normalizedDisplayName;
      }

      function formatAccountDisplayName(displayName, email, fallbackValue) {
        const trustedDisplayName = getTrustedDisplayName(displayName, email);
        if (trustedDisplayName) {
          return trustedDisplayName;
        }

        const emailDerivedDisplayName = formatEmailPrefixDisplayName(email);
        if (emailDerivedDisplayName) {
          return emailDerivedDisplayName;
        }

        const normalizedFallback = String(fallbackValue || "").trim();
        if (normalizedFallback) {
          return normalizedFallback;
        }

        return "Computer Agents";
      }

      function getWelcomeGreetingName(displayName, email) {
        const trustedDisplayName = getTrustedDisplayName(displayName, email);
        const preferredSource = trustedDisplayName || formatEmailPrefixDisplayName(email);
        const normalizedSource = String(preferredSource || "").replace(/\\s+/g, " ").trim();

        if (!normalizedSource) {
          return "there";
        }

        const firstSegment = normalizedSource.split(" ")[0] || normalizedSource;
        return firstSegment || "there";
      }

      function buildWelcomeGreeting(displayName, email) {
        const greetingName = getWelcomeGreetingName(displayName, email);
        const templateIndex = Math.floor(Math.random() * RUNNER_WELCOME_GREETING_TEMPLATES.length);
        return RUNNER_WELCOME_GREETING_TEMPLATES[templateIndex].replace("<name>", greetingName);
      }

