        function openServerSecretComposer(secret = null) {
          const normalizedSecret = secret ? normalizePlaygroundSecretRecord(secret) : null;
          setIsServerSecretDescriptionEditing(false);
          setServerSecretComposerState({
            open: true,
            secretId: normalizedSecret?.id || "",
            name: normalizedSecret?.name || "",
            description: normalizedSecret?.description || "",
            value: "",
            error: "",
            isSaving: false,
          });
        }

        function closeServerSecretComposer() {
          setIsServerSecretDescriptionEditing(false);
          setServerSecretComposerState({
            open: false,
            secretId: "",
            name: "",
            description: "",
            value: "",
            error: "",
            isSaving: false,
          });
        }

        function applyServerSecretDescriptionSelection(nextValue, nextSelectionStart, nextSelectionEnd = nextSelectionStart) {
          setIsServerSecretDescriptionEditing(true);
          setServerSecretComposerState((current) => ({
            ...current,
            description: nextValue,
            error: "",
          }));
          window.requestAnimationFrame(() => {
            const textarea = serverSecretDescriptionTextareaRef.current;
            if (!textarea) {
              return;
            }
            const maxLength = nextValue.length;
            const safeSelectionStart = Math.max(0, Math.min(nextSelectionStart, maxLength));
            const safeSelectionEnd = Math.max(safeSelectionStart, Math.min(nextSelectionEnd, maxLength));
            textarea.focus();
            textarea.setSelectionRange(safeSelectionStart, safeSelectionEnd);
            resizeEnvironmentDescriptionTextarea(textarea);
          });
        }

        function handleServerSecretDescriptionFormat(formatType) {
          const textarea = serverSecretDescriptionTextareaRef.current;
          if (!textarea) {
            return;
          }
          const value = String(serverSecretComposerState?.description || "");
          const selectionStart = typeof textarea.selectionStart === "number" ? textarea.selectionStart : value.length;
          const selectionEnd = typeof textarea.selectionEnd === "number" ? textarea.selectionEnd : selectionStart;
          let edit = null;

          if (formatType === "bold") {
            edit = buildWrappedEnvironmentDescriptionEdit(value, selectionStart, selectionEnd, "**");
          } else if (formatType === "italic") {
            edit = buildWrappedEnvironmentDescriptionEdit(value, selectionStart, selectionEnd, "*");
          } else if (formatType === "underline") {
            edit = buildWrappedEnvironmentDescriptionEdit(value, selectionStart, selectionEnd, "++");
          } else if (formatType === "list") {
            edit = buildEnvironmentDescriptionListEdit(value, selectionStart, selectionEnd);
          }

          if (!edit) {
            return;
          }

          applyServerSecretDescriptionSelection(edit.value, edit.selectionStart, edit.selectionEnd);
        }

        async function handleServerSecretComposerSubmit(event) {
          if (event?.preventDefault) {
            event.preventDefault();
          }
          const normalizedServerId = String(draftServer?.id || "").trim();
          const normalizedName = String(serverSecretComposerState.name || "").trim();
          const normalizedValue = String(serverSecretComposerState.value || "");
          const isEditingSecret = Boolean(serverSecretComposerState.secretId);
          if (!normalizedServerId || normalizedServerId === PLAYGROUND_SERVER_DRAFT_ID) {
            return;
          }
          if (!normalizedName) {
            setServerSecretComposerState((current) => ({
              ...current,
              error: "Name is required.",
            }));
            return;
          }
          if (!isEditingSecret && !normalizedValue) {
            setServerSecretComposerState((current) => ({
              ...current,
              error: "Secret value is required.",
            }));
            return;
          }

          setServerSecretComposerState((current) => ({
            ...current,
            isSaving: true,
            error: "",
          }));

          try {
            const body = {
              name: normalizedName,
              description: String(serverSecretComposerState.description || ""),
            };
            if (!isEditingSecret || normalizedValue) {
              body.value = normalizedValue;
            }
            const response = await fetch(
              isEditingSecret
                ? buildPlaygroundServerSecretUrl(backendUrl, normalizedServerId, serverSecretComposerState.secretId)
                : buildPlaygroundServerSecretsUrl(backendUrl, normalizedServerId),
              {
                method: isEditingSecret ? "PUT" : "POST",
                headers: {
                  ...requestHeaders,
                  "Content-Type": "application/json",
                },
                body: JSON.stringify(body),
              }
            );
            const data = await response.json().catch(() => ({}));
            if (!response.ok) {
              throw new Error(data?.message || data?.error || "Failed to save secret.");
            }
            const sourceSecrets = Array.isArray(data?.secrets) ? data.secrets : [];
            const secrets = sourceSecrets.map(normalizePlaygroundSecretRecord).filter(Boolean);
            setServerSecretsById((current) => ({
              ...current,
              [normalizedServerId]: secrets,
            }));
            setServerSecretsState({ error: "" });
            closeServerSecretComposer();
          } catch (error) {
            setServerSecretComposerState((current) => ({
              ...current,
              isSaving: false,
              error: error instanceof Error ? error.message : "Failed to save secret.",
            }));
          }
        }

        async function handleDeleteServerSecret(secret) {
          const normalizedSecret = normalizePlaygroundSecretRecord(secret);
          const normalizedServerId = String(draftServer?.id || "").trim();
          if (!normalizedSecret?.id || !normalizedServerId || normalizedServerId === PLAYGROUND_SERVER_DRAFT_ID) {
            return;
          }
          const confirmed = window.confirm('Delete secret "' + normalizedSecret.name + '"? Connected apps will no longer be able to read it.');
          if (!confirmed) {
            return;
          }
          setServerSecretsState({ error: "" });
          try {
            const response = await fetch(
              buildPlaygroundServerSecretUrl(backendUrl, normalizedServerId, normalizedSecret.id),
              {
                method: "DELETE",
                headers: requestHeaders,
              }
            );
            const data = await response.json().catch(() => ({}));
            if (!response.ok) {
              throw new Error(data?.message || data?.error || "Failed to delete secret.");
            }
            const sourceSecrets = Array.isArray(data?.secrets) ? data.secrets : [];
            const secrets = sourceSecrets.map(normalizePlaygroundSecretRecord).filter(Boolean);
            setServerSecretsById((current) => ({
              ...current,
              [normalizedServerId]: secrets,
            }));
          } catch (error) {
            setServerSecretsState({
              error: error instanceof Error ? error.message : "Failed to delete secret.",
            });
          }
        }

        async function createServerAgentRuntimeRun(serverId, input) {
          const normalizedServerId = String(serverId || "").trim();
          if (!normalizedServerId || normalizedServerId === PLAYGROUND_SERVER_DRAFT_ID) {
            return null;
          }

          setServerAgentRuntimeRunsState({
            error: "",
            message: "",
          });

          const response = await fetch(buildPlaygroundServerRunsUrl(backendUrl, normalizedServerId), {
            method: "POST",
            headers: {
              ...requestHeaders,
              "Content-Type": "application/json",
            },
            body: JSON.stringify(input || {}),
          });
          const data = await response.json().catch(() => ({}));
          if (!response.ok) {
            throw new Error(data?.message || data?.error || "Failed to start run.");
          }
          await loadServerAgentRuntimeRuns(normalizedServerId, { force: true });
          setServerAgentRuntimeRunsState({
            error: "",
            message: "Run started.",
          });
          return data?.run || null;
        }

        async function cancelServerAgentRuntimeRun(serverId, runId) {
          const normalizedServerId = String(serverId || "").trim();
          const normalizedRunId = String(runId || "").trim();
          if (!normalizedServerId || !normalizedRunId) {
            return false;
          }

          const response = await fetch(buildPlaygroundServerRunCancelUrl(backendUrl, normalizedServerId, normalizedRunId), {
            method: "POST",
            headers: requestHeaders,
          });
          const data = await response.json().catch(() => ({}));
          if (!response.ok) {
            throw new Error(data?.message || data?.error || "Failed to cancel run.");
          }
          await loadServerAgentRuntimeRuns(normalizedServerId, { force: true });
          setServerAgentRuntimeRunsState({
            error: "",
            message: "Run cancelled.",
          });
          return true;
        }

        function buildSanitizedEnvironmentPayload(environment) {
          const normalizedEnvironment = normalizePlaygroundEnvironmentRecord(environment);
          const profile = getPlaygroundEnvironmentComputeProfileConfig(normalizedEnvironment.computeProfile);
          const runtimes = Object.fromEntries(
            Object.entries(normalizedEnvironment?.runtimes || {}).filter(([, value]) => typeof value === "string" && value.trim())
          );
          const packages = {
            system: (normalizedEnvironment?.packages?.system || []).map((value) => String(value || "").trim()).filter(Boolean),
            python: (normalizedEnvironment?.packages?.python || []).map((value) => String(value || "").trim()).filter(Boolean),
            node: (normalizedEnvironment?.packages?.node || []).map((value) => String(value || "").trim()).filter(Boolean),
          };
          const environmentVariables = (normalizedEnvironment?.environmentVariables || [])
            .map((item) => ({
              key: String(item?.key || "").trim(),
              value: typeof item?.value === "string" ? item.value : "",
            }))
            .filter((item) => item.key);

          const preparedSecrets = (normalizedEnvironment?.secrets || [])
            .map((secret) => {
              const key = String(secret?.key || "").trim();
              const isExisting = existingSecretKeys.has(key);
              const wasModified = modifiedSecrets[key] !== undefined;
              if (isExisting && !wasModified) {
                return { key, value: "", _unchanged: true };
              }
              if (isExisting && wasModified) {
                return { key, value: modifiedSecrets[key] };
              }
              return {
                key,
                value: typeof secret?.value === "string" ? secret.value : "",
              };
            })
            .filter((secret) => secret.key && !secret._unchanged);

          const preparedMcpServers = (normalizedEnvironment?.mcpServers || [])
            .map((server) => {
              const normalizedServer = {
                id: server?.id,
                name: String(server?.name || "").trim(),
                enabled: server?.enabled !== false,
                type: server?.type === "http" ? "http" : "stdio",
                command: typeof server?.command === "string" ? server.command : "",
                url: typeof server?.url === "string" ? server.url : "",
                bearerToken: typeof server?.bearerToken === "string" ? server.bearerToken : "",
              };
              if (!normalizedServer.name) {
                return null;
              }
              if (normalizedServer.type === "http" && existingMcpTokenServers.has(normalizedServer.name) && modifiedMcpTokens[normalizedServer.name] === undefined) {
                normalizedServer.bearerToken = PLAYGROUND_MASKED_SECRET_VALUE;
              } else if (normalizedServer.type === "http" && modifiedMcpTokens[normalizedServer.name] !== undefined) {
                normalizedServer.bearerToken = modifiedMcpTokens[normalizedServer.name];
              }
              return normalizedServer;
            })
            .filter(Boolean);

          const documentation = (normalizedEnvironment?.documentation || [])
            .map((document, index) => ({
              id: typeof document?.id === "string" && document.id.trim() ? document.id : "doc-" + index,
              name: String(document?.name || "").trim() || ("Document " + (index + 1)),
              content: typeof document?.content === "string" ? document.content : "",
              mimeType: typeof document?.mimeType === "string" && document.mimeType.trim() ? document.mimeType : "text/plain",
            }))
            .filter((document) => document.name || document.content);

          const metadata = clonePlaygroundEnvironmentMetadata(normalizedEnvironment?.metadata);
          const pricing = metadata.pricing && typeof metadata.pricing === "object" && !Array.isArray(metadata.pricing)
            ? { ...metadata.pricing }
            : {};
          pricing.minutePrice = profile.minutePrice;

          return {
            name: String(normalizedEnvironment?.name || "").trim() || "Untitled Environment",
            runtimes,
            packages,
            dockerfileExtensions: typeof normalizedEnvironment?.dockerfileExtensions === "string" ? normalizedEnvironment.dockerfileExtensions : "",
            environmentVariables,
            secrets: preparedSecrets,
            setupScripts: (normalizedEnvironment?.setupScripts || []).map((value) => String(value || "")).filter((value) => value.trim()),
            mcpServers: preparedMcpServers,
            documentation,
            internetAccess: normalizedEnvironment?.internetAccess !== false,
            metadata: {
              ...metadata,
              computeProfile: profile.id,
              computeResources: {
                cpuCores: profile.cpuCores,
                memoryMb: profile.memoryMb,
              },
              pricing,
              guiEnabled: profile.guiEnabled,
              officeAppsEnabled: normalizedEnvironment?.officeAppsEnabled === true && profile.id === "desktop",
            },
          };
        }

      function buildSanitizedServerPayload(server) {
          const metadata = server?.metadata && typeof server.metadata === "object" && !Array.isArray(server.metadata)
            ? JSON.parse(JSON.stringify(server.metadata))
            : null;
          if (metadata?.runnerPlayground && typeof metadata.runnerPlayground === "object" && !Array.isArray(metadata.runnerPlayground)) {
            delete metadata.runnerPlayground.database;
            if (Object.keys(metadata.runnerPlayground).length === 0) {
              delete metadata.runnerPlayground;
            }
          }
          return {
            name: String(server?.name || "").trim() || "Untitled Server",
            description: typeof server?.description === "string" ? server.description : "",
            projectId: typeof server?.projectId === "string" && server.projectId.trim() ? server.projectId.trim() : null,
            kind: canonicalizePlaygroundServerKind(server?.kind),
            sourceType: ["manual", "computer", "git"].includes(server?.sourceType) ? server.sourceType : "manual",
            sourceEnvironmentId: typeof server?.sourceEnvironmentId === "string" && server.sourceEnvironmentId.trim() ? server.sourceEnvironmentId.trim() : null,
            sourcePath: typeof server?.sourcePath === "string" && server.sourcePath.trim() ? server.sourcePath : null,
            region: typeof server?.region === "string" && server.region.trim() ? server.region.trim() : "europe-west1",
            runtime: typeof server?.runtime === "string" && server.runtime.trim() ? server.runtime.trim() : "nodejs22",
            authMode: server?.authMode === "private" ? "private" : "public",
            serviceUrl: typeof server?.serviceUrl === "string" && server.serviceUrl.trim() ? server.serviceUrl.trim() : null,
            customDomain: typeof server?.customDomain === "string" && server.customDomain.trim() ? server.customDomain.trim() : null,
            cloudRunServiceName: typeof server?.cloudRunServiceName === "string" && server.cloudRunServiceName.trim() ? server.cloudRunServiceName.trim() : null,
            imageUrl: typeof server?.imageUrl === "string" && server.imageUrl.trim() ? server.imageUrl.trim() : null,
            status: ["draft", "deploying", "deployed", "failed", "inactive"].includes(server?.status) ? server.status : "draft",
            lastDeployedAt: typeof server?.lastDeployedAt === "string" && server.lastDeployedAt.trim() ? server.lastDeployedAt.trim() : null,
            metadata: metadata && Object.keys(metadata).length > 0 ? metadata : null,
          };
        }

        function buildSanitizedDatabasePayload(database) {
          return {
            name: String(database?.name || "").trim() || "Untitled Database",
            description: typeof database?.description === "string" ? database.description : "",
            projectId: typeof database?.projectId === "string" && database.projectId.trim() ? database.projectId.trim() : null,
            location: typeof database?.location === "string" && database.location.trim() ? database.location.trim() : "eur3",
            status: ["active", "provisioning", "error"].includes(database?.status) ? database.status : "active",
            metadata: database?.metadata && typeof database.metadata === "object" && !Array.isArray(database.metadata) ? database.metadata : null,
          };
        }

        function preserveTransientDraftEnvironmentRows(savedEnvironment, currentDraft) {
          if (!currentDraft) {
            return savedEnvironment;
          }

          const transientEnvironmentVariables = (currentDraft.environmentVariables || [])
            .filter((item) => !String(item?.key || "").trim())
            .map((item) => ({
              key: "",
              value: typeof item?.value === "string" ? item.value : "",
            }));
          const transientSecrets = (currentDraft.secrets || [])
            .filter((item) => !String(item?.key || "").trim())
            .map((item) => ({
              key: "",
              value: typeof item?.value === "string" ? item.value : "",
            }));
          const transientSetupScripts = (currentDraft.setupScripts || [])
            .filter((value) => !String(value || "").trim())
            .map((value) => String(value || ""));
          const transientMcpServers = (currentDraft.mcpServers || [])
            .filter((server) => !String(server?.name || "").trim())
            .map((server, index) => ({
              id: server?.id || "mcp-transient-" + index,
              name: "",
              enabled: server?.enabled !== false,
              type: server?.type === "http" ? "http" : "stdio",
              command: typeof server?.command === "string" ? server.command : "",
              url: typeof server?.url === "string" ? server.url : "",
              bearerToken: typeof server?.bearerToken === "string" ? server.bearerToken : "",
            }));

          if (
            transientEnvironmentVariables.length === 0
            && transientSecrets.length === 0
            && transientSetupScripts.length === 0
            && transientMcpServers.length === 0
          ) {
            return savedEnvironment;
          }

          return normalizePlaygroundEnvironmentRecord({
            ...savedEnvironment,
            environmentVariables: [
              ...(savedEnvironment.environmentVariables || []),
              ...transientEnvironmentVariables,
            ],
            secrets: [
              ...(savedEnvironment.secrets || []),
              ...transientSecrets,
            ],
            setupScripts: [
              ...(savedEnvironment.setupScripts || []),
              ...transientSetupScripts,
            ],
            mcpServers: [
              ...(savedEnvironment.mcpServers || []),
              ...transientMcpServers,
            ],
          });
        }

        async function persistEnvironmentRecord(environmentRecord) {
          if (!environmentRecord) {
            return;
          }

          const payload = buildSanitizedEnvironmentPayload(environmentRecord);
          let savedEnvironment = null;

          if (!environmentRecord.id || environmentRecord.id === PLAYGROUND_ENVIRONMENT_DRAFT_ID) {
            const createResponse = await fetch(backendUrl + "/environments", {
              method: "POST",
              headers: {
                ...requestHeaders,
                "Content-Type": "application/json",
              },
              body: JSON.stringify({
                name: payload.name,
                description: payload.description,
                environmentVariables: payload.environmentVariables,
                secrets: payload.secrets,
                setupScripts: payload.setupScripts,
                mcpServers: payload.mcpServers,
                documentation: payload.documentation,
                internetAccess: payload.internetAccess,
                metadata: payload.metadata,
              }),
            });
            const createData = await createResponse.json().catch(() => ({}));
            if (!createResponse.ok) {
              throw new Error(createData?.message || createData?.error || "Failed to create environment.");
            }

            const createdEnvironment = getPlaygroundEnvironmentResponseRecord(createData);
            if (!createdEnvironment?.id) {
              throw new Error("Environment creation response did not include an id.");
            }

            const updateResponse = await fetch(backendUrl + "/environments/" + encodeURIComponent(createdEnvironment.id), {
              method: "PUT",
              headers: {
                ...requestHeaders,
                "Content-Type": "application/json",
              },
              body: JSON.stringify(payload),
            });
            const updateData = await updateResponse.json().catch(() => ({}));
            if (!updateResponse.ok) {
              throw new Error(updateData?.message || updateData?.error || "Failed to update the new environment.");
            }
            savedEnvironment = getPlaygroundEnvironmentResponseRecord(updateData) || normalizePlaygroundEnvironmentRecord({
              ...createdEnvironment,
              ...payload,
            });
          } else {
            const updateResponse = await fetch(backendUrl + "/environments/" + encodeURIComponent(environmentRecord.id), {
              method: "PUT",
              headers: {
                ...requestHeaders,
                "Content-Type": "application/json",
              },
              body: JSON.stringify(payload),
            });
            const updateData = await updateResponse.json().catch(() => ({}));
            if (!updateResponse.ok) {
              throw new Error(updateData?.message || updateData?.error || "Failed to save environment.");
            }
            savedEnvironment = getPlaygroundEnvironmentResponseRecord(updateData) || normalizePlaygroundEnvironmentRecord({
              ...environmentRecord,
              ...payload,
              updatedAt: new Date().toISOString(),
            });
          }

          if (!savedEnvironment) {
            throw new Error("Environment save failed.");
          }

          return savedEnvironment;
        }

