          if (systemSkillFamilyId === "browser") return Globe;
          if (systemSkillFamilyId === "image_generation") return ImageIcon;
          if (systemSkillFamilyId === "video_generation") return Film;
          if (systemSkillFamilyId === "web_search") return Search;
