async function proxyUpstreamTaskJsonRequest(req, res, upstreamPath, method) {
  try {
    const upstreamUrl = parseUpstreamUrl(req, {});
    const body = method === "GET" || method === "HEAD"
      ? undefined
      : await readRequestBody(req);
    const apiKey = readOptionalApiKey(req, body);
    const requestUrl = new URL(req.url || "/", `http://localhost:${port}`);
    let upstream;

    if (apiKey) {
      const upstreamTarget = new URL(`${upstreamUrl}${upstreamPath}`);
      upstreamTarget.search = requestUrl.search;
      upstream = await fetch(upstreamTarget.toString(), {
        method,
        headers: {
          "Content-Type": "application/json",
          "X-API-Key": apiKey,
        },
        body: body === undefined ? undefined : JSON.stringify(body),
      });
    } else if (hasAiosSession(req)) {
      upstream = await fetchAiosTaskApi(req, upstreamPath, {
        method,
        headers: {
          "content-type": "application/json",
        },
        body: body === undefined ? undefined : JSON.stringify(body),
      });
    } else {
      return sendJson(res, 401, {
        error: "Unauthorized",
        message: "Sign in with Computer Agents or provide an API key.",
      });
    }

    const text = await upstream.text();
    let parsed = {};
    try {
      parsed = text ? JSON.parse(text) : {};
    } catch {
      parsed = { message: text };
    }

    return sendJson(res, upstream.status, parsed);
  } catch (error) {
    return sendJson(res, 502, {
      error: `Failed to proxy upstream ${method} task request`,
      message: error instanceof Error ? error.message : String(error),
    });
  }
}

function getAgentAssistantPresetVisiblePrompt(value) {
  const text = extractAgentAssistantPresetText(value);
  if (text.includes("Preset action: Optimize Agent based on latest threads.")) {
    return "Optimize Agent based on latest threads";
  }
  if (text.includes("Preset action: Analyze model & reasoning effort fit.")) {
    return "Analyze model & reasoning effort fit";
  }
  if (text.includes("Preset action: Analyze efficiency.")) {
    return "Analyze model & reasoning effort fit";
  }
  return "";
}

function extractAgentAssistantPresetText(value) {
  if (typeof value === "string") {
    return value;
  }
  if (Array.isArray(value)) {
    return value.map(extractAgentAssistantPresetText).filter(Boolean).join("\n");
  }
  if (value && typeof value === "object") {
    if (typeof value.text === "string") return value.text;
    if (typeof value.content === "string") return value.content;
    if (Array.isArray(value.content)) return extractAgentAssistantPresetText(value.content);
  }
  return String(value || "");
}

function isAgentAssistantPresetExecutionContent(value) {
  return Boolean(getAgentAssistantPresetVisiblePrompt(value));
}

function sanitizeAgentAssistantPresetMessage(message) {
  if (!message || typeof message !== "object" || Array.isArray(message)) {
    return message;
  }
  const visiblePrompt = getAgentAssistantPresetVisiblePrompt(message.content);
  if (!visiblePrompt || String(message.role || "").trim().toLowerCase() !== "user") {
    return message;
  }
  return {
    ...message,
    content: visiblePrompt,
  };
}

function sanitizeAgentAssistantPresetMessagesPayload(payload) {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return payload;
  }
  return {
    ...payload,
    ...(Array.isArray(payload.data)
      ? { data: payload.data.map(sanitizeAgentAssistantPresetMessage) }
      : {}),
    ...(Array.isArray(payload.messages)
      ? { messages: payload.messages.map(sanitizeAgentAssistantPresetMessage) }
      : {}),
  };
}

